-- Legados fictícios: um acerto completo e dois aguardando credor, com IDs referenciados.
DO $$DECLARE i integer;l uuid;pay uuid;receipt uuid;part uuid;BEGIN
 FOR i IN 1..3 LOOP
  l:=gen_random_uuid();pay:=gen_random_uuid();receipt:=CASE WHEN i=1 THEN gen_random_uuid() END;part:=gen_random_uuid();
  INSERT INTO public.lancamentos(id_lancamento,tipo,descricao,valor_total,data_ocorrencia,mes_referencia,tipo_origem,id_origem,status,criado_por_id) VALUES(l,'Despesa','Legado rateio v4 '||i,100,'2026-10-01','2026-10-01','Conta','40000000-4000-4000-8000-400000000001','Efetivado','10000000-1000-4000-8000-100000000001');
  INSERT INTO public.rateios(id_rateio,id_lancamento,id_usuario_responsavel,id_usuario_credor,valor_rateado,status,criado_por_id) VALUES(part,l,'10000000-1000-4000-8000-100000000002','10000000-1000-4000-8000-100000000001',50,'Pendente','10000000-1000-4000-8000-100000000001'),(gen_random_uuid(),l,'10000000-1000-4000-8000-100000000001','10000000-1000-4000-8000-100000000001',50,'Pendente','10000000-1000-4000-8000-100000000001');
  INSERT INTO public.lancamentos(id_lancamento,tipo,descricao,valor_total,data_ocorrencia,mes_referencia,tipo_origem,id_origem,status,criado_por_id) VALUES(pay,'Despesa','Acerto legado pagamento '||i,50,'2026-10-02','2026-10-01','Conta','40000000-4000-4000-8000-400000000002','Efetivado','10000000-1000-4000-8000-100000000002');
  IF receipt IS NOT NULL THEN INSERT INTO public.lancamentos(id_lancamento,tipo,descricao,valor_total,data_ocorrencia,mes_referencia,tipo_origem,id_origem,status,criado_por_id) VALUES(receipt,'Receita','Acerto legado recebimento',50,'2026-10-02','2026-10-01','Conta','40000000-4000-4000-8000-400000000001','Efetivado','10000000-1000-4000-8000-100000000001');END IF;
  INSERT INTO public.acertos_rateios(mes_referencia,id_usuario_devedor,id_usuario_credor,valor,data_pagamento,data_recebimento,status,forma_devedor,forma_credor,id_conta_devedor,id_conta_credor,id_lancamento_pagamento,id_lancamento_recebimento,ids_rateios,criado_por_id) VALUES('2026-10-01','10000000-1000-4000-8000-100000000002','10000000-1000-4000-8000-100000000001',50,'2026-10-02',CASE WHEN i=1 THEN '2026-10-02'::date END,CASE WHEN i=1 THEN 'Efetivado' ELSE 'Aguardando_Credor' END,'Novo',CASE WHEN i=1 THEN 'Novo' END,'40000000-4000-4000-8000-400000000002',CASE WHEN i=1 THEN '40000000-4000-4000-8000-400000000001'::uuid END,pay,receipt,ARRAY[part],'10000000-1000-4000-8000-100000000002');
 END LOOP;
END $$;
